import numpy as np

def make_obs(agent=None, reward=None, moving=None, obstacles=(), prev_agent=None):
    x = np.zeros((1, 500), dtype=np.float32)
    # wall border in channel 3
    for r in range(10):
        for c in range(10):
            if r in (0, 9) or c in (0, 9):
                x[0, (r * 10 + c) * 5 + 3] = 1.0
    def setcell(r, c, ch, val=1.0):
        x[0, (r * 10 + c) * 5 + ch] = val
    if agent is not None:
        setcell(agent[0], agent[1], 0)
    if reward is not None:
        setcell(reward[0], reward[1], 2)
    if moving is not None:
        setcell(moving[0], moving[1], 1)
    for o in obstacles:
        setcell(o[0], o[1], 3)
    if prev_agent is None:
        prev_agent = agent
    if prev_agent is not None:
        setcell(prev_agent[0], prev_agent[1], 4)
    return x

