import numpy as np

def make_obs(agent=None, moving=None, reward=None, obstacles=None, prev=None):
    grid = np.zeros((10, 10, 5), dtype=float)
    # wall border in channel 3
    for r in range(10):
        for c in range(10):
            if r == 0 or r == 9 or c == 0 or c == 9:
                grid[r, c, 3] = 1.0
    if agent is not None:
        r, c = agent
        grid[r, c, 0] = 1.0
    if moving is not None:
        r, c = moving
        grid[r, c, 1] = 1.0
    if reward is not None:
        r, c = reward
        grid[r, c, 2] = 1.0
    if obstacles is not None:
        for r, c in obstacles:
            grid[r, c, 3] = 1.0
    if prev is not None:
        for r, c in prev:
            grid[r, c, 4] = 1.0
    return grid.flatten()

conditions = []
conditions.append(("baseline agent(8,4)", make_obs(agent=(8,4))))
conditions.append(("agent(8,4) moving(6,1) above-left", make_obs(agent=(8,4), moving=(6,1))))
conditions.append(("agent(8,4) moving(6,4) above-center", make_obs(agent=(8,4), moving=(6,4))))
conditions.append(("agent(8,4) moving(6,7) above-right", make_obs(agent=(8,4), moving=(6,7))))
conditions.append(("agent(8,4) moving(7,1) closer-left", make_obs(agent=(8,4), moving=(7,1))))
conditions.append(("agent(8,4) moving(7,7) closer-right", make_obs(agent=(8,4), moving=(7,7))))
conditions.append(("agent(8,4) moving(8,1) same-row-left", make_obs(agent=(8,4), moving=(8,1))))
conditions.append(("agent(8,4) moving(8,7) same-row-right", make_obs(agent=(8,4), moving=(8,7))))

X = np.array([obs for _, obs in conditions])
logits = forward(X)
for (desc, _), lg in zip(conditions, logits):
